func Windows_Chmod(path string, mode uint32) (err error) {
	p, e := Windows_UTF16PtrFromString(path)
	if e != nil {
		return e
	}
	attrs, e := Windows_GetFileAttributes(p)
	if e != nil {
		return e
	}
	if mode&Windows_S_IWRITE != 0 {
		attrs &^= Windows_FILE_ATTRIBUTE_READONLY
	} else {
		attrs |= Windows_FILE_ATTRIBUTE_READONLY
	}
	return Windows_SetFileAttributes(p, attrs)
}

