func Windows_WSASendto(s Windows_Handle, bufs *Windows_WSABuf, bufcnt uint32, sent *uint32, flags uint32, to Windows_Sockaddr, overlapped *Windows_Overlapped, croutine *byte) (err error) {
	var rsa unsafe.Pointer
	var len int32
	if to != nil {
		rsa, len, err = to.sockaddr()
		if err != nil {
			return err
		}
	}
	r1, _, e1 := Windows_Syscall9(windows_procWSASendTo.Addr(), 9, uintptr(s), uintptr(unsafe.Pointer(bufs)), uintptr(bufcnt), uintptr(unsafe.Pointer(sent)), uintptr(flags), uintptr(unsafe.Pointer(rsa)), uintptr(len), uintptr(unsafe.Pointer(overlapped)), uintptr(unsafe.Pointer(croutine)))
	if r1 == windows_socket_error {
		if e1 != 0 {
			err = windows_errnoErr(e1)
		} else {
			err = Windows_EINVAL
		}
	}
	return err
}

