var windows_connectExFunc struct {
	once sync.Once
	addr uintptr
	err  error
}

func Windows_LoadConnectEx() error {
	windows_connectExFunc.once.Do(func() {
		var s Windows_Handle
		s, windows_connectExFunc.err = Windows_Socket(Windows_AF_INET, Windows_SOCK_STREAM, Windows_IPPROTO_TCP)
		if windows_connectExFunc.err != nil {
			return
		}
		defer Windows_CloseHandle(s)
		var n uint32
		windows_connectExFunc.err = Windows_WSAIoctl(s,
			Windows_SIO_GET_EXTENSION_FUNCTION_POINTER,
			(*byte)(unsafe.Pointer(&Windows_WSAID_CONNECTEX)),
			uint32(unsafe.Sizeof(Windows_WSAID_CONNECTEX)),
			(*byte)(unsafe.Pointer(&windows_connectExFunc.addr)),
			uint32(unsafe.Sizeof(windows_connectExFunc.addr)),
			&n, nil, 0)
	})
	return windows_connectExFunc.err
}

func windows_connectEx(s Windows_Handle, name unsafe.Pointer, namelen int32, sendBuf *byte, sendDataLen uint32, bytesSent *uint32, overlapped *Windows_Overlapped) (err error) {
	r1, _, e1 := Windows_Syscall9(windows_connectExFunc.addr, 7, uintptr(s), uintptr(name), uintptr(namelen), uintptr(unsafe.Pointer(sendBuf)), uintptr(sendDataLen), uintptr(unsafe.Pointer(bytesSent)), uintptr(unsafe.Pointer(overlapped)), 0, 0)
	if r1 == 0 {
		if e1 != 0 {
			err = error(e1)
		} else {
			err = Windows_EINVAL
		}
	}
	return
}

func Windows_ConnectEx(fd Windows_Handle, sa Windows_Sockaddr, sendBuf *byte, sendDataLen uint32, bytesSent *uint32, overlapped *Windows_Overlapped) error {
	err := Windows_LoadConnectEx()
	if err != nil {
		return errorspkg.New("failed to find ConnectEx: " + err.Error())
	}
	ptr, n, err := sa.sockaddr()
	if err != nil {
		return err
	}
	return windows_connectEx(fd, ptr, n, sendBuf, sendDataLen, bytesSent, overlapped)
}

