// Readlink returns the destination of the named symbolic link.
func Windows_Readlink(path string, buf []byte) (n int, err error) {
	pathp, err := Windows_UTF16PtrFromString(path)
	if err != nil {
		return -1, err
	}
	fd, err := Windows_CreateFile(pathp, Windows_GENERIC_READ, 0, nil, Windows_OPEN_EXISTING,
		Windows_FILE_FLAG_OPEN_REPARSE_POINT|Windows_FILE_FLAG_BACKUP_SEMANTICS, 0)
	if err != nil {
		return -1, err
	}
	defer Windows_CloseHandle(fd)

	rdbbuf := make([]byte, Windows_MAXIMUM_REPARSE_DATA_BUFFER_SIZE)
	var bytesReturned uint32
	err = Windows_DeviceIoControl(fd, Windows_FSCTL_GET_REPARSE_POINT, nil, 0, &rdbbuf[0], uint32(len(rdbbuf)), &bytesReturned, nil)
	if err != nil {
		return -1, err
	}

	rdb := (*windows_reparseDataBuffer)(unsafe.Pointer(&rdbbuf[0]))
	var s string
	switch rdb.ReparseTag {
	case Windows_IO_REPARSE_TAG_SYMLINK:
		data := (*windows_symbolicLinkReparseBuffer)(unsafe.Pointer(&rdb.reparseBuffer))
		p := (*[0xffff]uint16)(unsafe.Pointer(&data.PathBuffer[0]))
		s = Windows_UTF16ToString(p[data.SubstituteNameOffset/2 : (data.SubstituteNameOffset+data.SubstituteNameLength)/2])
		if data.Flags&windows__SYMLINK_FLAG_RELATIVE == 0 {
			if len(s) >= 4 && s[:4] == `\??\` {
				s = s[4:]
				switch {
				case len(s) >= 2 && s[1] == ':': // \??\C:\foo\bar
					// do nothing
				case len(s) >= 4 && s[:4] == `UNC\`: // \??\UNC\foo\bar
					s = `\\` + s[4:]
				default:
					// unexpected; do nothing
				}
			} else {
				// unexpected; do nothing
			}
		}
	case windows__IO_REPARSE_TAG_MOUNT_POINT:
		data := (*windows_mountPointReparseBuffer)(unsafe.Pointer(&rdb.reparseBuffer))
		p := (*[0xffff]uint16)(unsafe.Pointer(&data.PathBuffer[0]))
		s = Windows_UTF16ToString(p[data.SubstituteNameOffset/2 : (data.SubstituteNameOffset+data.SubstituteNameLength)/2])
		if len(s) >= 4 && s[:4] == `\??\` { // \??\C:\foo\bar
			s = s[4:]
		} else {
			// unexpected; do nothing
		}
	default:
		// the path is not a symlink or junction but another type of reparse
		// point
		return -1, Windows_ENOENT
	}
	n = copy(buf, []byte(s))

	return n, nil
}

