// newProcThreadAttributeList allocates a new [procThreadAttributeListContainer], with the requested maximum number of attributes.
func windows_newProcThreadAttributeList(maxAttrCount uint32) (*windows_procThreadAttributeListContainer, error) {
	var size uintptr
	err := windows_initializeProcThreadAttributeList(nil, maxAttrCount, 0, &size)
	if err != Windows_ERROR_INSUFFICIENT_BUFFER {
		if err == nil {
			return nil, errorspkg.New("unable to query buffer size from InitializeProcThreadAttributeList")
		}
		return nil, err
	}
	const LMEM_FIXED = 0
	alloc, err := windows_localAlloc(LMEM_FIXED, uint32(size))
	if err != nil {
		return nil, err
	}
	// size is guaranteed to be ≥1 by InitializeProcThreadAttributeList.
	al := &windows_procThreadAttributeListContainer{data: (*windows__PROC_THREAD_ATTRIBUTE_LIST)(unsafe.Pointer(alloc))}
	err = windows_initializeProcThreadAttributeList(al.data, maxAttrCount, 0, &size)
	if err != nil {
		return nil, err
	}
	al.pointers = make([]unsafe.Pointer, 0, maxAttrCount)
	return al, err
}

// Update modifies the ProcThreadAttributeList using UpdateProcThreadAttribute.
func (al *windows_procThreadAttributeListContainer) update(attribute uintptr, value unsafe.Pointer, size uintptr) error {
	al.pointers = append(al.pointers, value)
	return windows_updateProcThreadAttribute(al.data, 0, attribute, value, size, nil, nil)
}

// Delete frees ProcThreadAttributeList's resources.
func (al *windows_procThreadAttributeListContainer) delete() {
	windows_deleteProcThreadAttributeList(al.data)
	Windows_LocalFree(Windows_Handle(unsafe.Pointer(al.data)))
	al.data = nil
	al.pointers = nil
}

// List returns the actual ProcThreadAttributeList to be passed to StartupInfoEx.
func (al *windows_procThreadAttributeListContainer) list() *windows__PROC_THREAD_ATTRIBUTE_LIST {
	return al.data
}

// RegEnumKeyEx enumerates the subkeys of an open registry key.
// Each call retrieves information about one subkey. name is
// a buffer that should be large enough to hold the name of the
// subkey plus a null terminating character. nameLen is its
// length. On return, nameLen will contain the actual length of the
// subkey.
//
// Should name not be large enough to hold the subkey, this function
// will return ERROR_MORE_DATA, and must be called again with an
// appropriately sized buffer.
//
// reserved must be nil. class and classLen behave like name and nameLen
// but for the class of the subkey, except that they are optional.
// lastWriteTime, if not nil, will be populated with the time the subkey
// was last written.
//
// The caller must enumerate all subkeys in order. That is
// RegEnumKeyEx must be called with index starting at 0, incrementing
// the index until the function returns ERROR_NO_MORE_ITEMS, or with
// the index of the last subkey (obtainable from RegQueryInfoKey),
// decrementing until index 0 is enumerated.
//
// Successive calls to this API must happen on the same OS thread,
// so call [runtime.LockOSThread] before calling this function.
func Windows_RegEnumKeyEx(key Windows_Handle, index uint32, name *uint16, nameLen *uint32, reserved *uint32, class *uint16, classLen *uint32, lastWriteTime *Windows_Filetime) (regerrno error) {
	return windows_regEnumKeyEx(key, index, name, nameLen, reserved, class, classLen, lastWriteTime)
}

