func Windows_CreateFile(name *uint16, access uint32, mode uint32, sa *Windows_SecurityAttributes, createmode uint32, attrs uint32, templatefile int32) (handle Windows_Handle, err error) {
	handle, err = windows_createFile(name, access, mode, sa, createmode, attrs, templatefile)
	if handle != Windows_InvalidHandle {
		// CreateFileW can return ERROR_ALREADY_EXISTS with a valid handle.
		// We only want to return an error if the handle is invalid.
		err = nil
	}
	return handle, err
}
